import type {PracticeQuestion} from './practice-bank';
type Translation=Pick<PracticeQuestion,'prompt'|'answer'|'explanation'> & {options?:string[];rubric?:string[]};
const choice=(prompt:string,options:string[],correct:number,explanation:string):Translation=>({prompt,options,answer:options[correct],explanation});
const fill=(prompt:string,answer:string,explanation:string):Translation=>({prompt,answer,explanation});
const short=(prompt:string,answer:string,explanation:string,rubric:string[]):Translation=>({prompt,answer,explanation,rubric});
const code=(prompt:string,explanation:string,rubric:string[]):Translation=>({prompt,answer:'One reference implementation is shown below. Equivalent solutions that satisfy the requirements are also valid.',explanation,rubric});
export const practiceEnglish:Record<string,Translation>={
'p-go-c01':choice('Two Go slices share an underlying array. What happens when an existing element is modified without reallocation?',['The other slice can never change','The other slice can observe the change if it covers that position','The entire array is copied automatically','It always panics'],1,'Copying a slice does not copy its elements. Overlapping slices refer to the same array positions. An append may allocate a different array if capacity is insufficient, so sharing must not be assumed indefinitely.'),
'p-go-c02':choice('What does a receiver observe after a buffered channel is closed while it still contains values?',['An immediate panic','Only zero values','Buffered values first, then a zero value with ok=false','It blocks forever'],2,'Closing a channel prevents further sends but does not discard buffered values. In v, ok := <-ch, ok becomes false after those values are drained. Sending to a closed channel panics.'),
'p-go-c03':choice('Given var p *T = nil; var x any = p, what is x == nil?',['true','false','A compile error','It depends on the fields of T'],1,'An interface is nil only when it has neither a dynamic type nor a dynamic value. Here the dynamic type is *T, so the interface is non-nil even though its dynamic value is a nil pointer.'),
'p-go-c04':choice('A function executes defer A() followed by defer B(). In what order are they called when it returns normally?',['A then B','B then A','Concurrently','In random order'],1,'Deferred calls run in last-in, first-out order. Function values and arguments are evaluated when the defer statement executes; invocation is delayed until the surrounding function returns. Captured variables in closures require separate analysis.'),
'p-go-c05':choice('Several goroutines read and write the same ordinary map. Which approach is appropriate?',['Only increase map capacity','Add sleeps to the writes','Protect all related accesses with a lock, or give one goroutine ownership','Recover from panics and continue'],2,'An ordinary map does not support arbitrary concurrent reads and writes. Synchronization provides mutual exclusion and visibility. A run without a panic does not prove freedom from data races; locking writes but leaving reads unprotected is insufficient.'),
'p-go-c06':choice('Which statement about context cancellation is correct?',['It forcibly terminates all child goroutines','Workers must observe Done or check Err and stop cooperatively','It closes every business channel automatically','It automatically rolls back every database operation'],1,'Cancellation is a cooperative signal, not a forced interruption. Blocking calls should support context, and workers must exit and release resources. Database transactions still require the appropriate API handling.'),
'p-be-c01':choice('For a composite index (a,b), which condition most directly matches its leftmost prefix?',['Only b=2','a=1 AND b=2','Any function applied to b','All queries are equivalent'],1,'The B-tree is ordered by a, then b. Equality on both columns can use the contiguous prefix. A condition on b alone cannot be assumed to locate rows the same way. Confirm the actual plan with EXPLAIN.'),
'p-be-c02':choice('What does transaction atomicity primarily mean?',['Every statement always runs in parallel','The changes of a transaction commit or roll back as a unit','Reads never block','All SQL statements automatically use an index'],1,'Atomicity concerns all-or-nothing completion. Isolation concerns visibility between concurrent transactions, and durability concerns preserving committed changes. These are different properties.'),
'p-be-c03':choice('What does it mean for GET to be idempotent?',['Repeated responses must be byte-for-byte identical','Repeating an identical request has the same intended server effect as performing it once','Access logs are never written','Every request must hit a cache'],1,'Idempotency describes the intended effect on server state, not identical responses. Resources may change over time, and incidental actions such as logging can still occur.'),
'p-be-c04':choice('Many hot cache keys expire at the same time. What risk does this create?',['A cache avalanche','Only a deadlock','An automatic increase in hit rate','TCP loses idempotency'],0,'Simultaneous cache misses can concentrate traffic on the origin and overwhelm it. TTL jitter, staged warming, rate limits and graceful degradation help. A single hot key expiring is usually described as a cache stampede or hot-key breakdown.'),
'p-be-c05':choice('What must a consumer of an at-least-once delivery system handle?',['Messages are guaranteed never to repeat','Business idempotency and duplicate messages','Elimination of all retries','Sorting only by message length'],1,'At-least-once delivery may repeat messages. Stable business IDs, unique constraints and transactions can prevent duplicate charges or fulfillment. An in-memory set alone does not survive restarts.'),
'p-be-c06':choice('Why must a TCP application define message boundaries?',['TCP delivers each application message separately','TCP is a byte stream; one read need not correspond to one send','TCP offers no reliability','Every read can return only one byte'],1,'TCP provides an ordered byte stream and does not preserve application write boundaries. Length prefixes or delimiters are common. Receivers must handle partial messages, multiple messages and maximum lengths.'),
'p-go-f01':fill('The idiomatic boolean variable in v, ____ := <-ch indicates whether a channel receive returned a value. Fill in its name.','ok','ok is false when the channel is closed and its buffer is drained. A received element can itself be a zero value while ok is true, so checking v alone is insufficient.'),
'p-go-f02':fill('Which counting synchronization type in the sync package is commonly used to wait for a group of goroutines? ____','WaitGroup','WaitGroup uses Add, Done and Wait to track tasks. A common pattern calls Add before launching each goroutine and defers Done inside it. WaitGroup does not propagate errors by itself.'),
'p-go-f03':fill('The capacity of a slice s is obtained with the built-in function ____(s).','cap','len is the current length. cap is the available capacity from the start of the slice to the end of its underlying array. Appending beyond capacity requires a new underlying array.'),
'p-go-f04':fill('To schedule file cleanup when the surrounding function returns, write ____ f.Close().','defer','A defer runs when its surrounding function exits, including normal panic unwinding. It does not run at the end of the current loop iteration, so a large loop can accumulate open resources.'),
'p-go-f05':fill('When a context is canceled or its deadline expires, the channel returned by Done is ____. Use an English past participle.','closed','Closing the channel can notify multiple listeners. Cancellation does not forcibly kill a goroutine: the worker should select on ctx.Done() and exit.'),
'p-go-f06':fill('Which predefined Go type alias represents a Unicode code point? ____','rune','rune is an alias for int32. Strings store bytes; ranging over a string decodes UTF-8 code points. One visible character may consist of several code points.'),
'p-be-f01':fill('Which SQL clause filters the result of grouped aggregation? ____','HAVING','WHERE filters input rows before grouping. HAVING filters groups after aggregation, for example GROUP BY user_id HAVING COUNT(*) > 1.'),
'p-be-f02':fill('To count all table rows, including rows whose fields contain NULL, use COUNT(____).','*','COUNT(*) counts rows. COUNT(column) counts rows where that expression is not NULL, so the results may differ when NULL values exist.'),
'p-be-f03':fill('What does DNS stand for? ____','Domain Name System','DNS maps names to records. A records contain IPv4 addresses and AAAA records contain IPv6 addresses. TTL and other cache behavior determine how long cached records remain usable.'),
'p-be-f04':fill('HTTP status 429 means Too Many ____.','Requests','429 is commonly used for rate limiting. Clients should back off, and should honor Retry-After when the server provides it.'),
'p-be-f05':fill('The lifetime of a cache entry is commonly abbreviated as ____.','TTL','TTL means time to live. Spreading key expiry times can reduce simultaneous misses, but it does not replace capacity planning and protection for origin traffic.'),
'p-be-f06':fill('In ACID, the letter D stands for ____.','Durability','Durability means successful commits are preserved within the system’s promised failure model. Logs, flushing policies and storage guarantees contribute to this property.'),
'p-go-s01':short('Explain the difference between len and cap, and how append affects slice sharing.','len is the number of directly indexable elements. cap is the underlying array capacity available from the slice start. append can reuse that array when capacity permits, or allocate and copy otherwise. Assign the returned slice to retain its updated header.','Separate the slice descriptor from its underlying array. Shared slices observe changes to overlapping positions. Do not rely on a particular capacity growth multiplier.',['Distinguish length from capacity','Explain reuse versus reallocation','Discuss shared mutations and the returned slice']),
'p-go-s02':short('How would you diagnose and prevent a goroutine leak?','Inspect exit conditions, blocked channel operations, lock waits and external I/O. Use cancellation, timeouts and clear channel ownership to let workers terminate. Observe goroutine profiles and count trends under load.','A leak means work no longer has value but cannot exit, not simply that many goroutines exist. Both producers and consumers need cancellation paths. Calling cancel at the top is ineffective if lower layers never observe it.',['Identify blocking operations and exit paths','Make channel operations and I/O cancelable','Verify cleanup with profiles or monitoring']),
'p-go-s03':short('Why can an error interface containing a nil pointer compare unequal to nil? How can you avoid this?','An interface carries a dynamic type and a dynamic value. Assigning a nil *MyError to error preserves the type, so the interface is non-nil. Return a literal nil on success instead of a typed nil pointer.','Callers usually test err != nil. A typed nil inside the interface may falsely signal failure and may cause a nil-pointer problem when Error is called.',['Explain dynamic type and value','Show the typed-nil case','Return literal nil on success']),
'p-go-s04':short('How do you choose between Mutex and RWMutex?','Mutex provides exclusive access. RWMutex allows concurrent readers but requires exclusive access for writing. A read-side operation must not mutate shared state. Choose based on read/write ratio, critical-section duration and measurements.','RWMutex is not automatically faster for read-heavy workloads. Coordination overhead can outweigh benefits for short sections. Do not attempt to upgrade a held read lock directly to a write lock.',['Explain exclusive versus shared-read access','Synchronize every relevant shared access','Avoid lock upgrades and measure performance']),
'p-go-s05':short('Design cancellation and timeout propagation for an HTTP request that calls several downstream services.','Derive a timeout context from the request context and defer cancel. Pass it to downstream HTTP and database calls. Workers observe Done and release resources such as response bodies on every exit path. Leave room in the overall timeout budget.','Replacing the request context with Background breaks the cancellation chain. Budgets should include queueing and execution. Cancellation also cannot undo external side effects that already completed.',['Propagate the request context','Set budgets and release cancellation resources','Explain worker exit and side-effect boundaries']),
'p-go-s06':short('What distinct problems do unit tests, benchmarks and race detection address?','Unit tests validate behavior and edge cases. Benchmarks measure execution time and allocation. Race detection finds data races on paths actually executed. Combine them and include concurrency and failure cases.','Passing tests only covers exercised paths. Keep unrelated setup out of benchmark measurements. A clean race-detector run does not prove safety under every possible schedule.',['Describe each tool’s purpose','Use meaningful boundary and concurrency cases','Explain coverage and measurement limitations']),
'p-be-s01':short('After a database update, how would you handle cache consistency and origin pressure?','A common cache-aside write path commits the database update and then deletes the cached value. On a read miss, load from the database and cache with a TTL. Retry failed invalidation reliably; consider stale concurrent refills, request coalescing and temporary inconsistency.','The database and cache usually do not share a transaction, so these two steps do not guarantee strong consistency. Delayed double deletion is also not correct under every schedule. Design around the business tolerance for stale data.',['Describe read and write paths','Analyze failed invalidation and stale refills','Provide compensation and origin protection']),
'p-be-s02':short('How would you investigate a slow SQL query?','Identify slow queries and actual parameters. Inspect EXPLAIN, rows scanned, index usage, sorting and table lookups. Check lock waits, returned data volume and data distribution. Change queries or indexes based on evidence, then compare plans and real latency.','Adding indexes blindly increases write and storage costs. Plans depend on data distribution. Fast results on a tiny sample do not guarantee fast production behavior.',['Start with slow-query evidence and parameters','Inspect scans, indexes, sorting and locks','Validate improvements and write overhead']),
'p-be-s03':short('Payment callbacks may arrive repeatedly. How do you prevent duplicate credits?','Use a stable order or payment transaction ID as an idempotency key with a database unique constraint. Verify callback authenticity and amount. Record processing and update the balance in one transaction. Return the recorded result for repeats.','Checking before writing has a race window. A process-local lock does not coordinate multiple instances. Unique constraints and transactions provide a database safeguard; external effects require additional reliable messaging or compensation.',['Verify the callback and use a stable key','Combine uniqueness with atomic transactions','Handle concurrent duplicates and retry responses']),
'p-be-s04':short('A consumer finishes processing but crashes before acknowledging the message. What happens?','With at-least-once delivery, the message may be redelivered. The consumer should recognize duplicate business operations and store results using transactions and unique constraints. Acknowledge after success, and use backoff and dead-letter handling for persistent failures.','Acknowledging first can lose work; acknowledging afterward can cause repeated work. These failure windows explain why consumer idempotency is necessary.',['Explain redelivery','Process before acknowledgment and make it idempotent','Include retries and dead-letter handling']),
'p-be-s05':short('Explain a token bucket and distinguish it from a concurrency limit.','Tokens refill at a configured rate up to a maximum capacity. A request consumes a token; capacity permits limited bursts. A concurrency limit caps simultaneous in-flight work, whereas a rate limit controls admissions over time.','Slow requests may exhaust resources even at a modest arrival rate, so both controls can be useful. Distributed rate limiting also involves shared state, clocks and behavior when the limiting service is unavailable.',['Explain refill rate and bucket capacity','Distinguish rate from in-flight concurrency','Consider bursts and distributed failure cases']),
'p-be-s06':short('How can a TCP service decode application messages reliably?','Define a protocol using length prefixes or delimiters and maintain a receive buffer. For a length prefix, read the complete header and then the complete body. Enforce size limits and handle EOF, timeouts and invalid input.','A single Read may return part of a header or data spanning multiple messages. The number of network reads does not equal the number of business messages.',['Define unambiguous framing','Handle partial and multiple messages','Validate lengths and handle errors']),
'p-go-k01':code('Write Go twoSum(nums []int, target int) (int, int). Return any two distinct indices that sum to target, or -1,-1 if none exist. Example: [3,3], 6 → 0,1. Assume int arithmetic does not overflow.','Look up the complement before inserting the current element to avoid using one index twice. Average time is O(n), space O(n). Test duplicate values, negative numbers and no solution.',['Never reuse the same index','Handle duplicates and no solution','Explain average time and space complexity']),
'p-go-k02':code('Reverse a string by Unicode code points in Go. Example: "Go语言" → "言语oG". You do not need to preserve grapheme clusters.','Swapping UTF-8 bytes can corrupt multibyte characters. Converting to rune handles code points, but some emoji and combining characters span multiple code points. Time and extra space are O(n).',['Swap runes rather than bytes','Handle empty and non-ASCII strings','Distinguish code points from visible characters']),
'p-go-k03':code('In Go, check matching brackets in a string containing only ()[]{}. Treat other characters as invalid. "([])" is true, "([)]" is false, and an empty string is true.','A stack holds unmatched opening brackets. Each closing bracket must match the stack top. Check that the stack is empty at the end. Time is O(n), worst-case space O(n).',['Check empty-stack cases and bracket types','Reject other characters','Check for remaining open brackets']),
'p-go-k04':code('Implement binary search in Go for an ascending integer slice. Return any matching index for target, or -1 if absent.','Maintain the closed interval [lo,hi]. Exclude the midpoint after each comparison. An empty slice naturally skips the loop. Time is O(log n), extra space O(1).',['Keep interval and loop conditions consistent','Shrink the interval each iteration','Test empty slices and boundary values']),
'p-go-k05':code('Write Go send(ctx context.Context, ch chan<- int, v int) error. Return nil on a successful send, or ctx.Err() if cancellation occurs while waiting. Assume the caller ensures ch is never closed.','select makes the send wait cancelable. If sending and cancellation are both ready, either branch may win; cancellation is not strictly prioritized. Import context.',['Select over send and cancellation together','Return the context error correctly','Explain simultaneous readiness and channel ownership']),
'p-go-k06':code('Implement a concurrency-safe Go Counter with Inc() and Value(). You may use sync.Mutex.','Both reads and writes need synchronization. Pointer receivers avoid copying a mutex after use. Import sync. Do not expose a mutable reference that bypasses the lock.',['Lock both reads and writes','Use pointer receivers without copying the lock','Release the lock correctly']),
'p-go-k07':code('Deduplicate a []int in Go while preserving first-occurrence order. [2,1,2,3,1] becomes [2,1,3]. Do not modify the input.','Iterate the original slice to preserve order; use the map only for membership checks. Iterating the map to build output would lose the required ordering. Average time and extra space are O(n).',['Preserve first-occurrence order','Leave the input unchanged','Handle empty input and duplicates']),
'p-go-k08':code('Write Go load(path string) ([]byte,error). Read a file and, on failure, wrap the path and original error while preserving errors.Is traversal.','%w creates a wrapping chain; %v only formats text. A caller can use errors.Is(err, fs.ErrNotExist) to inspect the cause. Import os and fmt. Preserve the original error.',['Check the read error','Wrap with %w','Return bytes and nil on success']),
'p-be-k01':code('Given orders(id,user_id,amount,status), find each user’s total paid amount, keeping only totals greater than 1000. Paid rows have status="paid". amount uses an exact numeric type.','WHERE filters paid rows before GROUP BY. HAVING filters the aggregate result. SUM(amount)>1000 cannot be placed directly in WHERE at the same query level.',['Filter paid rows before aggregation','Group by user_id and sum amount','Filter totals with HAVING']),
'p-be-k02':code('Given users(id,name) and orders(id,user_id), return id and name for users with no orders. orders.user_id may contain NULL.','A correlated NOT EXISTS checks for matching orders. NOT IN can produce UNKNOWN when its subquery contains NULL. A LEFT JOIN with a non-null order primary key checked for NULL is another valid solution.',['Correlate orders with the current user','Select users with no matching order','Avoid the NOT IN / NULL trap']),
'p-be-k03':code('Given events(id,created_at), with unique id and non-null created_at, use descending (created_at,id) order. Fetch the next 20 rows after the previous page’s last (:time,:id).','The unique id breaks timestamp ties, and cursor comparisons must match sort direction. A suitable composite index can avoid deep OFFSET scans. Concurrent changes to ordering fields can still affect results across pages.',['Use timestamp and unique id for stable ordering','Match cursor comparisons to sort direction','Explain indexing and concurrent data changes']),
'p-be-k04':code('Given employees(id,department_id,salary), with non-null salary, return all employees who earn the highest salary in their department, including ties. Use SQL with window-function support.','DENSE_RANK assigns the same rank to equal salaries within a department, preserving all first-place ties. ROW_NUMBER would keep only one employee. Compute the rank in a subquery and filter it outside.',['Partition by department','Sort salaries descending and keep ties','Filter rank one in the outer query']),
};
